import React from 'react';
import { Link } from 'react-router-dom';
import OutlineIcon from '../icons/OutlineIcon.jsx';
import './TopHeaderBar.css';

export default function TopHeaderBar() {
  return (
    <div className="mmc-topbar">
      <Link to="/subscription" className="mmc-topbar-inner">
        <span className="mmc-topbar-icon" aria-hidden="true">
          <OutlineIcon name="sparkle" size={14} />
        </span>
        <strong>Best offer</strong>
        <span className="mmc-topbar-dot" aria-hidden="true" />
        <span className="mmc-topbar-copy">Wish offer — launch plans from ₹1</span>
      </Link>
    </div>
  );
}
